/** A module function minus its leading context parameter. */
export type Op<F> = F extends (ta: ActionsCtx, ...a: infer A) => infer R ? (...a: A) => R : never;

/** Bind a module function to one context so it can be passed around as a value. */
export function bindOp<F extends (ta: ActionsCtx, ...a: never[]) => unknown>(ta: ActionsCtx, f: F): Op<F> {
  return ((...a: never[]) => f(ta, ...a)) as Op<F>;
}
